grid = [
    [0, 0, 6, 0, 0, 1, 5, 5, 5, 0, 0],
    [0, 6, 0, 0, 0, 1, 5, 5, 0, 0, 5],
    [0, 0, 0, 0, 0, 1, 5, 5, 5, 5, 0],
    [0, 0, 0, 0, 6, 1, 0, 0, 5, 0, 5],
    [0, 6, 0, 0, 0, 1, 5, 5, 0, 0, 0]
]

# Color swap transformation
output = [row[:] for row in grid]
for r in range(len(grid)):
    for c in range(len(grid[0])):
        if output[r][c] == 6:
            output[r][c] = 5
        elif output[r][c] == 5:
            output[r][c] = 6

print("Output grid:")
for row in output:
    print(row)

result_str = str(output)
print("\nResult string:", result_str)

# Maybe the rule is: combine left and right shapes in middle, where 6s become 5s on right side positions
# Or: the output is the right side with left shapes mirrored into it

grid = [
    [0, 0, 6, 0, 0, 1, 5, 5, 5, 0, 0],
    [0, 6, 0, 0, 0, 1, 5, 5, 0, 0, 5],
    [0, 0, 0, 0, 0, 1, 5, 5, 5, 5, 0],
    [0, 0, 0, 0, 6, 1, 0, 0, 5, 0, 5],
    [0, 6, 0, 0, 0, 1, 5, 5, 0, 0, 0]
]

rows = 5
cols = 11
sep_col = 5

# Try: start with right side, add mirrored left shapes as 6s
output = [[0]*cols for _ in range(rows)]
for r in range(rows):
    for c in range(sep_col, cols):
        output[r][c] = grid[r][c]  # copy right side including separator

# Then add mirrored 6s from left side
for r in range(rows):
    for c_left in range(sep_col - 1):  # cols 0-4
        if grid[r][c_left] == 6:
            mirror_c = cols - 1 - c_left
            output[r][mirror_c] = 6

print("Start with right side + mirrored 6s:")
for row in output:
    print(row)

# Try another: start with LEFT, then add mirrored 5s  
output2 = [[0]*cols for _ in range(rows)]
for r in range(rows):
    for c in range(0, sep_col):
        output2[r][c] = grid[r][c]  # copy left side

# Add mirrored 5s from right side
for r in range(rows):
    for c_right in range(sep_col, cols):
        if grid[r][c_right] == 5:
            mirror_c_left = cols - 1 - c_right
            if mirror_c_left < sep_col:
                output2[r][mirror_c_left] = 5

print("\nStart with left side + mirrored 5s (only if in left zone):")
for row in output2:
    print(row)

